// ─── Cover assets (base64 HiSolution template) ──────────────────────────────
const COVER_BG_B64 = "";
const COVER_LOGO_B64 = "";

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-darkrisk-internal-secret, x-darkrisk-esteso-cron-secret',
};

function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store', ...corsHeaders },
  });
}

function escHtml(s: unknown): string {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// Vera password in chiaro: scarta URL/path/dominio/JSON/segnali "leaks signal".
// L'utente vuole SOLO credenziali reali, non link (pastebin, URL prodotto, ecc.).
function isRealCleartextPassword(rawValue: unknown): boolean {
  const v = String(rawValue ?? '').trim();
  if (!v) return false;
  if (v.length < 4 || v.length > 80) return false;
  const lower = v.toLowerCase();
  // Scarta URL / path / dominio / JSON / segnali
  if (lower.includes('http') || v.includes('//') || v.includes('/') || v.includes('\\')) return false;
  if (v.includes('{') || v.includes('}') || v.includes('[') || v.includes(']') || v.includes('"')) return false;
  if (v.includes('\t') || /\s/.test(v)) return false;
  if (lower.includes('pastebin') || lower.includes('leaks signal') || lower.includes('darkrisk')) return false;
  if (lower.includes('linea') || lower.includes('signal') || lower.includes('exposure')) return false;
  if (/^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$/i.test(v)) return false; // email pura
  if (/^(?:[a-z0-9-]+\.)+[a-z]{2,}$/i.test(v)) return false; // dominio puro
  if (/^\d{1,8}$/.test(v)) return false; // solo cifre (timestamp/id)
  if (/^[a-f0-9]{32,}$/i.test(v)) return false; // hash
  // Deve contenere almeno una lettera o un carattere tipico password
  if (!/[a-zA-Z]/.test(v) && !/[!@#$%^&*_\-+=?.]/.test(v)) return false;
  return true;
}

// Estrae la vera password in chiaro da un hit sensibile (clear_value preferito)
function realPasswordValue(hit: any): string | null {
  const candidates = [hit?.clear_value, hit?.masked_value, hit?.value].map((x) => String(x ?? '').trim());
  for (const c of candidates) {
    if (isRealCleartextPassword(c)) return c;
  }
  return null;
}

// Legenda nomenclatura fonti (bucket) — coerente con la dashboard
const BUCKET_LEGEND: Array<{ category: string; description: string }> = [
  { category: 'Data Leak', description: 'Credenziali e dati da database compromessi (pubblici e riservati).' },
  { category: 'Bot Logs / Infostealer', description: 'Dati esfiltrati da malware infostealer (Redline, Vidar, Lumma): cookie e credenziali browser.' },
  { category: 'Dark Web', description: 'Servizi nascosti Tor (.onion) e I2P (.i2p): esposizione su rete anonima.' },
  { category: 'Paste', description: 'Documenti su siti di paste (es. Pastebin): possibili dump di credenziali.' },
  { category: 'Web pubblico', description: 'Pagine web pubblicamente indicizzate che citano il dominio/asset.' },
  { category: 'Web governativo', description: 'Siti governativi pubblici che citano l\'asset.' },
  { category: 'WHOIS / Dominio', description: 'Dati di registrazione e configurazione del dominio.' },
  { category: 'Dumpster / Misti', description: 'Dati eterogenei ad alto valore non classificati altrove.' },
];

// Etichetta leggibile per un bucket tecnico (coerente con src/lib/darkrisk/bucketLegend.ts)
function bucketLabel(bucket: unknown): string {
  const raw = String(bucket || '').trim();
  if (!raw) return 'Fonte non classificata';
  const k = raw.toLowerCase();
  const exact: Record<string, string> = {
    'leaks.private.general': 'Data Leak riservati', 'leaks.public.general': 'Data Leak pubblici',
    'leaks.public.wikileaks': 'Leak WikiLeaks / Cryptome', 'leaks.restricted': 'Data Leak riservati',
    'leaks.logs': 'Bot Logs / Infostealer', 'darknet.tor': 'Dark Web — Tor (.onion)',
    'darknet.i2p': 'Dark Web — I2P (.i2p)', 'pastes': 'Paste pubblici', 'paste': 'Paste pubblici',
    'whois': 'Registrazioni dominio (WHOIS)', 'dns': 'Record DNS', 'usenet': 'Usenet',
    'documents.public.scihub': 'Documenti pubblici', 'dumpster': 'Dati misti (Dumpster)',
    'web.public.gov': 'Web governativo — US', 'web.gov.ru': 'Web governativo — Russia',
  };
  if (exact[k]) return exact[k];
  if (k.startsWith('web.public.')) { const tld = k.split('.').slice(2).join('.'); return tld ? `Web pubblico — ${tld}` : 'Web pubblico'; }
  if (k.startsWith('web.gov.')) return 'Web governativo';
  if (k.startsWith('leaks.')) return 'Data Leak';
  if (k.startsWith('darknet.')) return 'Dark Web';
  if (k.startsWith('dumpster')) return 'Dati misti (Dumpster)';
  if (k.startsWith('documents.')) return 'Documenti pubblici';
  return raw.replace(/[._]/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
}

function fmtDate(v: unknown): string {
  const s = String(v || '');
  if (!s) return '—';
  const d = new Date(s);
  if (isNaN(d.getTime())) return s.slice(0, 10) || '—';
  return d.toLocaleDateString('it-IT', { day: '2-digit', month: '2-digit', year: 'numeric' });
}

function fmtDateTime(v: unknown): string {
  const s = String(v || '');
  if (!s) return '—';
  const d = new Date(s);
  if (isNaN(d.getTime())) return s.slice(0, 16) || '—';
  return d.toLocaleString('it-IT', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
}

// Normalizza un record DNS in righe { ttl, data }.
// I dati reali arrivano in forma DNS-over-HTTPS: { type, query, answers:[{ ttl, data, name, type }] }.
// Gestisce anche forme legacy (array di stringhe, oggetti { exchange, priority }, stringa singola).
function dnsAnswers(entry: unknown): Array<{ ttl: number | null; data: string }> {
  if (entry == null) return [];
  const e = entry as any;
  if (Array.isArray(e?.answers)) {
    return e.answers
      .map((a: any) => ({
        ttl: Number.isFinite(Number(a?.ttl)) ? Number(a.ttl) : null,
        data: String(a?.data ?? '').replace(/^"|"$/g, '').trim(),
      }))
      .filter((a: { data: string }) => a.data);
  }
  const arr = Array.isArray(e) ? e : [e];
  return arr
    .map((v: any) => {
      if (v && typeof v === 'object') {
        if (v.exchange) return { ttl: null, data: `${v.priority ?? ''} ${v.exchange}`.trim() };
        if (v.data != null) return { ttl: Number.isFinite(Number(v.ttl)) ? Number(v.ttl) : null, data: String(v.data).trim() };
        return { ttl: null, data: '' };
      }
      return { ttl: null, data: String(v ?? '').trim() };
    })
    .filter((a: { data: string }) => a.data);
}

// TTL numerico (secondi) → etichetta breve leggibile.
function ttlLabel(ttl: number | null): string {
  if (ttl == null || !Number.isFinite(ttl)) return '—';
  if (ttl >= 86400) return `${Math.round(ttl / 86400)}g`;
  if (ttl >= 3600) return `${Math.round(ttl / 3600)}h`;
  if (ttl >= 60) return `${Math.round(ttl / 60)}m`;
  return `${ttl}s`;
}

function sevBadge(sev: string): string {
  const map: Record<string, string> = {
    critical: '#dc2626', high: '#ea580c', medium: '#d97706', low: '#2563eb', info: '#6b7280',
  };
  const color = map[sev?.toLowerCase()] ?? '#6b7280';
  return `<span style="background:${color};color:#fff;padding:2px 8px;border-radius:4px;font-size:11px;font-weight:600;text-transform:uppercase">${escHtml(sev)}</span>`;
}

function tr(...cells: string[]): string {
  return `<tr>${cells.map((c, i) => `<td style="padding:6px 10px;border:1px solid #374151;${i === 0 ? 'font-weight:600;background:#1e293b' : ''}">${c}</td>`).join('')}</tr>`;
}

function trh(...cells: string[]): string {
  return `<tr>${cells.map((c) => `<th style="padding:8px 10px;background:#1e3a5f;color:#93c5fd;border:1px solid #374151;text-align:left;font-size:12px;text-transform:uppercase;letter-spacing:.04em">${c}</th>`).join('')}</tr>`;
}

function table(header: string[], rows: string[][]): string {
  if (rows.length === 0) return `<p style="color:#6b7280;font-style:italic">Nessun dato disponibile.</p>`;
  return `<table style="width:100%;border-collapse:collapse;font-size:13px;margin:8px 0">
    <thead>${trh(...header)}</thead>
    <tbody>${rows.map((r) => tr(...r.map(escHtml))).join('')}</tbody>
  </table>`;
}

function section(title: string, content: string, level = 2): string {
  const tag = `h${level}`;
  return `<${tag} style="color:#60a5fa;margin-top:28px;margin-bottom:10px;padding-bottom:6px;border-bottom:1px solid #374151">${escHtml(title)}</${tag}>${content}`;
}

function subsection(title: string, content: string): string {
  return section(title, content, 3);
}

function para(text: string): string {
  return `<p style="color:#d1d5db;line-height:1.6;margin:8px 0">${text}</p>`;
}

function ul(items: string[]): string {
  return `<ul style="color:#d1d5db;padding-left:20px;margin:8px 0">${items.map((i) => `<li style="margin:4px 0">${i}</li>`).join('')}</ul>`;
}

